/**
 * Wire types of the `/v1` API. Shapes come from the server's OpenAPI document (`schema.ts`,
 * regenerated by `pnpm --filter web gen:api`); this file only names them and adds what the
 * document does not carry (the `Api` surface, query shapes, `/v1/doctor`).
 */
import type { components, paths } from './schema.js';

type Schemas = components['schemas'];
type Json200<Op> = Op extends { responses: { 200: { content: { 'application/json': infer R } } } }
  ? R
  : never;

export type Agent = Schemas['Agent'];
export type Settings = Json200<paths['/v1/settings']['get']>;
export type JudgeTransport = Settings['judge.transport'];
export type BudgetMode = Settings['budget.mode'];
export type Source = Schemas['Source'];
export type SourceStatus = Source['status'];
export type DetectedSource = Schemas['DetectedSource'];
export type SkillRepo = Schemas['SkillRepo'];
export type DetectedSkillRepo = Schemas['DetectedSkillRepo'];
export type Job = Schemas['Job'];
export type JobStatus = Job['status'];
export type JudgeTestResult = Json200<paths['/v1/judge/test']['post']>;
export type TrendSummary = Schemas['TrendSummary'];
export type RubricRate = TrendSummary['rubrics'][number];
export type SessionSummary = Schemas['SessionSummary'];
export type SessionGrade = SessionSummary['grades'][number];
export type SessionDetail = Schemas['SessionDetail'];
export type TraceEvent = Schemas['TraceEvent'];
export type EventKind = TraceEvent['kind'];
export type SessionResultFilter = NonNullable<
  paths['/v1/sessions']['get']['parameters']['query']
>['result'] &
  string;

export type Doctor = Schemas['DoctorReport'];
export type DoctorCheck = Doctor['checks'][number];

export interface SessionQuery {
  q?: string | undefined;
  agent?: Agent | undefined;
  result?: SessionResultFilter | undefined;
  cursor?: string | undefined;
  limit?: number | undefined;
}

export interface Page<T> {
  items: T[];
  nextCursor: string | null;
}

export type EventFilter = 'all' | 'errors' | 'evidence';

export interface EventQuery {
  filter: EventFilter;
  cursor?: string | undefined;
  limit?: number | undefined;
}

/** The API surface the SPA uses. `client.ts` implements it over HTTP, `mock.ts` over fixtures. */
export interface Api {
  getSettings(): Promise<Settings>;
  patchSettings(patch: Partial<Omit<Settings, 'judge.api_key_set'>>): Promise<Settings>;
  putJudgeKey(apiKey: string): Promise<void>;
  testJudge(body: { transport: JudgeTransport; apiKey?: string }): Promise<JudgeTestResult>;
  listSources(): Promise<Source[]>;
  detectSources(): Promise<DetectedSource[]>;
  addSource(body: { agent: Agent; path: string }): Promise<Source>;
  listSkillRepos(): Promise<SkillRepo[]>;
  detectSkillRepos(): Promise<DetectedSkillRepo[]>;
  putGlobalSkillRepo(path: string): Promise<SkillRepo>;
  copyStarterRubrics(): Promise<{ copied: string[] }>;
  patchSkillRepo(id: string, body: { enabled: boolean }): Promise<SkillRepo>;
  startImport(): Promise<Job>;
  getJob(id: string): Promise<Job>;
  getTrendSummary(days: number): Promise<TrendSummary>;
  listSessions(query: SessionQuery): Promise<Page<SessionSummary>>;
  getSession(id: string): Promise<SessionDetail>;
  listEvents(id: string, query: EventQuery): Promise<Page<TraceEvent> & { total: number }>;
  exchangeToken(token: string): Promise<void>;
  getDoctor(): Promise<Doctor>;
}
